# 固定回归向量，预期值由独立 Python 算法预先计算。
VECTORS = [('"a"\n"b"\n', 'false'), ('"aa"\n"aab"\n', 'false'), ('"anagram"\n"nagaram"\n', 'true'), ('"rat"\n"car"\n', 'false'), ('"a"\n"a"\n', 'true'), ('"abc"\n"abc"\n', 'true'), ('"abc"\n"abcd"\n', 'false'), ('"aaaa"\n"aaa"\n', 'false'), ('"z"\n"zzzz"\n', 'false'), ('"ab"\n"ba"\n', 'true'), ('"abc"\n"abd"\n', 'false'), ('""\n""\n', 'false')]

def samples():
    return VECTORS[:2]

def cases():
    return [x[0] for x in VECTORS[2:]]

def expected_cases():
    return VECTORS
